   "lead": "Regno Unito e Unione Europea hanno raggiunto una bozza di accordo per eliminare le burocrazie e i controlli sulle esportazioni e importazioni di cibo e prodotti animali legati alla Brexit. La misura, che dovrebbe entrare in vigore nel primo trimestre del 2028, rappresenta uno dei passaggi più rilevanti nel processo di revisione dei rapporti tra le due parti. L'intesa precede il vertice bilaterale previsto nei prossimi giorni di questo mese e punta a facilitare gli scambi commerciali riducendo i tempi e i costi delle procedure doganali.",
   "more": [
    "La decisione di abolire i controlli burocratici sulle derrate alimentari si inserisce nelle trattative volute dal governo britannico per ammorbidire le barriere commerciali sorgente dopo l'uscita dell'imbarcazione comunitaria dal mercato unico. Ridurre le verifiche ai confini punta a contenere i costi sostenuti dalle imprese esportatrici e importatrici."
   ],
