   "id": "z9c020290",
   "sez": "mondo",
   "titolo": "Attacchi con droni delle RSF evidenziano le divisioni tra Sudan ed Etiopia",
   "orig": "Deadly RSF drone attacks reveal deep divisions between Sudan and Ethiopia",
   "lead": "In seguito agli attacchi, Khartoum ha chiesto l'intervento delle Nazioni Unite per accertare le responsabilità e gestire la crisi regionale. Le tensioni lungo la frontiera condivisa riflettono la complessità dell'instabilità in Africa orientale, alimentata dalle ingerenze esterne e dal protrarsi del conflitto civile sudanese. Lo riferisce Al Jazeera.",
   "more": [
    "Il conflitto tra l'esercito regolare sudanese e i paramilitari delle RSF ha generato una vasta emergenza umanitaria nel Corno d'Africa. Il coinvolgimento indiretto e le divergenze tra gli Stati confinanti complicano i tentativi di mediazione internazionale volti a fermare i combattimenti."
   ],
