   "id": "z3079a7cc",
   "sez": "mondo",
   "titolo": "L'Iran avverte gli Stati Uniti: la responsabilità di evitare la guerra spetta a Washington",
   "orig": "Iran: \"Ora sta agli Usa evitare guerra\"",
   "lead": "Il presidente del parlamento iraniano, Mohammad Bagher Ghalibaf, ha dichiarato che la responsabilità di scongiurare un conflitto armato aperto ricade interamente sugli Stati Uniti. Durante il suo intervento, l'esponente politico di Teheran ha affermato che le forze armate del Paese sono in massimo stato di allerta, pronte alla battaglia e con la determinazione di rispondere a qualsiasi aggressione militare. Le affermazioni giungono in una fase di estrema tensione nello Stretto di Hormuz e nell'intero Medio Oriente. Lo riferisce Rai News.",
   "more": [
    "Le dichiarazioni della dirigenza iraniana s'inseriscono nel quadro delle crescenti manovre militari nella regione. Lo scontro verbale e gli incidenti navali od aerei rischiano di compromettere gli sforzi di mediazione avviati dai Paesi terzi per ristabilire la stabilità."
   ],
