   "id": "zef1780b3",
   "sez": "mondo",
   "titolo": "Corea del Sud e Turchia rafforzano la cooperazione sul nucleare e sulla difesa",
   "orig": "(LEAD) Lee, Erdogan agree to strengthen cooperation in nuclear power plants, defense industry",
   "lead": "Il presidente sudcoreano Lee Jae-myung e il presidente turco Recep Tayyip Erdogan si sono incontrati a Seul, concordando di intensificare la cooperazione nei settori dell'energia nucleare e dell'industria della difesa. I due leader hanno firmato diversi accordi per ampliare le produzioni congiunte e il trasferimento tecnologico. Durante il vertice bilaterale è stata anche ribadita l'intenzione di coordinare le iniziative di pace per la stabilità nella penisola coreana e nelle aree interessate da conflitti internazionali, compresa l'Ucraina.",
   "more": [
    "Le intese industriali tra Seul e Ankara riflettono l'espansione dei programmi sudcoreani di esportazione di tecnologie per l'energia atomica e sistemi di difesa verso i Paesi della NATO e del Medio Oriente, consolidando i legami economici e strategici tra le due nazioni."
   ],
