   "sez": "economia",
   "titolo": "L'inflazione in Georgia sale al 5,9% ad ottobre",
   "orig": "Georgia’s Annual Inflation at 5.9% in October 2026",
   "lead": "Secondo i dati diffusi dall'Ufficio Nazionale di Statistica, l'inflazione annua in Georgia si è attestata al 5,9% nel mese di ottobre, registrando un incremento dello 0,9% rispetto al mese precedente. Il rialzo dei prezzi al consumo è stato determinato principalmente dai rincari nel settore abitativo e delle forniture di acqua, energia elettrica e gas, aumentati del 10,1%. Nel frattempo, in altri Paesi della regione come il Kazakistan e la Turchia si registrano dinamiche di progressivo rallentamento inflazionistico.",
   "more": [
    "L'andamento dei prezzi nei Paesi caucasici e dell'Asia centrale riflette le fluttuazioni dei costi dell'energia e dei generi alimentari. Il monitoraggio dell'inflazione consente alle banche centrali di calibrare i tassi d'interesse per tutelare il potere d'acquisto dei cittadini."
   ],
