   "id": "za641e438",
   "sez": "cultura",
   "titolo": "Taika Waititi attacca la critica dopo l'insuccesso del suo ultimo film",
   "orig": "‘Sad lost souls’: Taika Waititi lambasts critics after Klara and the Sun box-office disaster",
   "lead": "Il regista Taika Waititi ha espresso durissime polemiche nei confronti dei critici cinematografici in seguito allo scarso successo al botteghino registrato dal suo film \"Klara e il Sole\", tratto dal romanzo del premio Nobel Kazuo Ishiguro. L'autore ha definito le recensioni negative come giudizi di anime smarrite e superate, sostenendo di realizzare le proprie opere per il grande pubblico, che ha invece attribuito valutazioni decisamente più favorevoli sulle piattaforme online rispetto agli esperti di settore.",
   "more": [
    "Il divario tra le valutazioni dei critici professionisti e il gradimento del pubblico è un fenomeno frequente nel cinema contemporaneo. La risposta del regista evidenzia le tensioni tra le dinamiche commerciali dei botteghini e la ricezione analitica delle opere cinematografiche."
   ],
