   "id": "z8c985ef8",
   "sez": "adolescenti",
   "titolo": "Un sistema di intelligenza artificiale protegge i comunitari e gli orsi polari",
   "orig": "The camera keeping a bear-y close watch for polar bears",
   "lead": "Un innovativo sistema di monitoraggio visivo chiamato Bear-vision impiega l'intelligenza artificiale per individuare l'avvicinamento degli orsi polari ai centri abitati. La tecnologia segnala tempestivamente la presenza dei plantigradi, offrendo alle comunità locali un allarme preventivo per evitare pericoli ed aggressioni. L'iniziativa mira a tutelare la sicurezza dei residenti e al tempo stesso a salvaguardare la vita degli orsi polari, prevenendo scontri dannosi nelle regioni artiche.",
   "more": [
    "La convivenza tra comunità umane ed fauna selvatica nelle zone polari è resa complessa dai cambiamenti climatici che riducono l'habitat naturale degli orsi. L'uso di sensori e algoritmi consente di gestire i contatti tra uomini e animali senza ricorrere ad abbattimenti."
   ],
