   "sez": "musica",
   "titolo": "Justin Timberlake racconta l'incidente del Super Bowl 2004 in una nuova docuserie",
   "orig": "Justin Timberlake torna sulla debacle del Super Bowl in una docuserie feat. Janet Jackson",
   "lead": "Il cantante Justin Timberlake ripercorrerà la controversia del famigerato incidente d'abito avvenuto durante lo spettacolo dell'intervallo del Super Bowl del 2004 in una nuova serie documentario in quattro puntate, prodotta per Apple TV e in uscita a dicembre. Il progetto vedrà la partecipazione della cantante Janet Jackson e rianalizzerà l'impatto mediatico ed esecutivo dell'episodio sulla carriera di entrambi gli artisti e sull'industria dell'intrattenimento televisivo americano.",
   "more": [
    "L'incidente del Super Bowl 2004 portò all'introduzione di rigide norme di censura e differite nella televisione statunitense. La docuserie riapre la discussione sul trattamento mediatico riservato ai due artisti e sulla percezione pubblica degli eventi dal vivo."
   ],
