   "sez": "italia",
   "titolo": "Funerali di Stato per i quattro militari caduti: la proposta di Crosetto",
   "orig": "Crosetto: un monumento per i 4 militari",
   "lead": "Durante i funerali solenni tenutisi per i quattro militari italiani deceduti in servizio, il ministro della Difesa Guido Crosetto ha reso omaggio ai caduti definendoli la parte migliore del Paese. Nel suo discorso commemorativo, il ministro ha proposto l'erezione di un monumento in memoria del loro sacrificio e della loro dedizione alle istituzioni nazionali. Alle esequie hanno preso parte le più alte cariche dello Stato e rappresentanti delle forze armate. Lo riferisce Rai News.",
   "more": [
    "Le cerimonie solenni per i militari caduti rappresentano un momento di unità nazionale ed espressione del cordoglio delle istituzioni. La proposta di erigere un monumento punta a perpetuare il ricordo del servizio prestato dai soldati nelle missioni dello Stato."
   ],
