   "titolo": "Ott Tänak tornerà nel WRC nel 2027 con la scuderia Toyota",
   "orig": "Estonia's Ott Tänak to make WRC comeback in 2027 with Toyota",
   "lead": "Il pilota di rally estone Ott Tänak farà il suo ritorno ufficiale nel World Rally Championship (WRC) a partire dalla stagione 2027 al volante di una vettura della Toyota. L'annuncio è stato dato martedì dal team giapponese, confermando l'accordo con il campione estone per disputare le prossime tappe del mondiale. Il ritorno di Tänak rafforza la squadra in vista dei futuri impegni sportivi nelle competizioni automobilistiche internazionali. Lo riferisce ERR News.",
   "more": [
    "Il World Rally Championship è la principale competizione mondiale per auto da rally. Il ritorno di piloti esperti nelle scuderie di vertice contribuisce a innalzare la competitività del campionato e a sviluppare le nuove tecnologie delle vetture da corsa."
   ],
