   "id": "z9eb220b7",
   "sez": "mondo",
   "titolo": "Settant'anni fa la prima trasmissione televisiva de Il mago di Oz negli Stati Uniti",
   "orig": "Good News in History, November 3",
   "lead": "Settant'anni fa, il 3 novembre, il celebre film \"Il mago di Oz\" veniva trasmesso per la prima volta in televisione negli Stati Uniti. La trasmissione registrò un successo straordinario, catturando l'attenzione del 53% degli spettatori televisivi americani. Il riscontro di pubblico fu così elevato da trasformare la messa in onda dell'opera cinematografica in un appuntamento annuale per le famiglie. Tre anni dopo, l'emittente CBS programmò nuovamente il film durante le festività, ottenendo un seguito di telespettatori ancora maggiore. Lo riferisce Good News Network.",
   "more": [
    "Tratto dal celebre romanzo di L. Frank Baum del 1900, il film \"Il mago di Oz\" uscì nei cinema nel 1939. La transizione alla diffusione televisiva negli anni Cinquanta contribuì in modo decisivo a consolidare la pellicola come un classico intramontabile della cultura popolare e dell'intrattenimento per famiglie negli Stati Uniti."
   ],
