   "id": "zdbf7189e",
   "sez": "salute",
   "titolo": "Organizzazioni sanitarie chiedono all'OMS di revisionare i limiti di nitrati nell'acqua potabile",
   "orig": "Cut down ‘outdated’ nitrate limit in drinking water, health and environmental groups tell WHO",
   "lead": "Diverse organizzazioni per la salute e per l'ambiente hanno chiesto all'Organizzazione Mondiale della Sanità di revisionare i limiti relativi alla presenza di nitrati nell'acqua potabile, definiti ormai obsoleti. Secondo i gruppi promotori dell'appello, le norme attuali non riflettono i recenti dati scientifici, i quali evidenziano come anche basse concentrazioni di nitrati possano essere correlate all'insorgenza di tumori e a casi di nascite premature. Le associazioni sollecitano quindi un aggiornamento urgente dei parametri di sicurezza idrica globale.",
   "more": [
    "I nitrati sono composti chimici ampiamente utilizzati nei fertilizzanti agricoli che possono filtrare nelle falde acquifere e contaminare l'acqua potabile. La costante revisione delle soglie di tolleranza da parte delle autorità sanitarie internazionali è essenziale per prevenire rischi a lungo termine per la salute umana, in particolare per i soggetti vulnerabili."
   ],
