   "titolo": "Intelligenza artificiale: per un vescovo svizzero la Chiesa deve guidare la formazione etica",
   "orig": "IA, un vescovo svizzero: la Chiesa sia guida nella formazione",
   "lead": "Durante un incontro promosso a Berna dalla Chiesa e dall'episcopato svizzero, il vescovo ausiliare di Basilea Josef Stübi hariflesso sull'importanza che la Chiesa svolga un ruolo guida nella formazione sull'intelligenza artificiale. Il presule ha evidenziato la necessità di trovare risposte concrete alle numerose questioni etiche e sociali sollevate dall'impiego degli algoritmi. Ispirandosi al principio della dignità umana, l'iniziativa intende orientare i fedeli e la comunità verso un uso consapevole e responsabile delle nuove tecnologie digitali. Lo riferisce Vatican News (italiano).",
   "more": [
    "Il dibattito etico sull'intelligenza artificiale coinvolge in modo crescente le istituzioni religiose, impegnate a valutare l'impatto degli algoritmi sulla società moderna. La riflessione ecclesiale punta a promuovere uno sviluppo tecnologico al servizio dell'essere umano, prevenendo disuguaglianze e garantendo la tutela dei valori fondamentali e della centralità della persona."
   ],
