   "id": "z4048ed24",
   "sez": "musica",
   "titolo": "Roma ospita la decima edizione del festival di musica elettronica Manifesto",
   "orig": "Kode9, Alessandro Cortini, Populous, Laura Agnusdei e Blak Saagan fra i protagonisti della X edizione di Manifesto (Roma, 25-29 novembre)",
   "lead": "Dal 25 al 29 novembre si terrà a Roma la decima edizione del festival Manifesto, evento dedicato al dialogo tra la musica elettronica e altri linguaggi sonori. La rassegna celebrerà dieci anni di sperimentazione e contaminazioni artistiche che spaziano dal dub al dubstep, fino al jazz e alle sonorità globali. Tra i principali protagonisti annunciati figurano artisti di rilievo come Kode9, Alessandro Cortini, Populous, Laura Agnusdei e Blak Saagan, pronti ad animare il ricco programma di incontri e performance. Lo riferisce OndaRock.",
   "more": [
    "I festival di musica elettronica e sperimentale rappresentano spazi fondamentali per la ricerca sonora contemporanea. Attraverso l'incontro tra generi diversi come dubstep, ambient e jazz, queste manifestazioni favoriscono l'innovazione artistica e offrono al pubblico percorsi di ascolto anticonvenzionali all'interno del panorama culturale urbano."
   ],
