   "id": "z954347f1",
   "sez": "italia",
   "titolo": "Sondaggi Swg: calano Fratelli d'Italia e Forza Italia, sale il centrosinistra",
   "orig": "Sondaggi politici, Fratelli d'Italia e Forza Italia calano e il centrosinistra allunga",
   "lead": "Secondo l'ultima rilevazione del sondaggio politico eseguito dall'istituto Swg per l'emittente La7, i partiti di maggioranza Fratelli d'Italia e Forza Italia registrano un calo nelle preferenze degli elettori. Contestualmente, la coalizione di centrosinistra amplifica il proprio distacco, sostenuta dalle percentuali in crescita del Partito Democratico e del Movimento 5 Stelle. All'interno dello schieramento di centrodestra si segnala invece un recupero della Lega. Le nuove stime mostrano un mutamento negli orientamenti dell'elettorato italiano. Lo riferisce la Repubblica.",
   "more": [
    "I sondaggi d'opinione politica rilevano periodicamente le oscillazioni nel consenso dei cittadini nei confronti delle forze di governo e di opposizione. Tali rilevazioni offrono uno spaccato dell'orientamento dell'elettorato, influenzato dal dibattito pubblico, dall'azione dell'esecutivo e dai temi economici e sociali del momento."
   ],
