   "titolo": "Calano i prezzi di benzina e diesel in Moldavia secondo le tariffe dell'ANRE",
   "orig": "Petrol and diesel prices will fall on Wednesday. ANRE has set new fuel prices",
   "lead": "In Moldavia i prezzi al dettaglio di benzina e gasolio subiranno un calo nella giornata di mercoledì. L'Agenzia Nazionale per la Regolamentazione dell'Energia (ANRE) ha stabilito i nuovi listini ufficiali del carburante, fissando una riduzione di 22 bani al litro per la benzina a 95 ottani e di 10 bani per il diesel standard. La decisione dell'autorità regolatrice adegua i prezzi della rete distributiva ai parametri di mercato. Lo riferisce IPN (inglese).",
   "more": [
    "Il prezzo dei carburanti al dettaglio in diversi Paesi è soggetto a regolamentazione periodica da parte di agenzie statali competenti. I listini vengono aggiornati in base all'andamento delle quotazioni internazionali del petrolio greggio, al tasso di cambio della moneta locale e ai costi di importazione e distribuzione della rete."
   ],
