   "titolo": "John Tree crea la lampada scultorea Hoop in legno di pino per Vaarni",
   "orig": "John Tree forms sculptural Hoop lamp from pine for Vaarni",
   "lead": "Il designer John Tree ha ideato la lampada da tavolo monolitica \"Hoop\" per il marchio finlandese Vaarni, realizzando una struttura scultorea che combina legno di pino massiccio e impiallacciatura sottile. L'oggetto di design si distingue per il contrasto tra il blocco di supporto dalle linee quasi brutaliste e il paralume circolare. L'opera punta a valorizzare le qualità materiali del pino attraverso forme geometriche pulite ed essenziali. Lo riferisce Dezeen.",
   "more": [
    "Il design nordico contemporaneo fa ampio uso del legno naturale di provenienza locale per creare arredi e complementi d'illuminazione sostenibili. L'impiego del pino lavorato con tecniche tradizionali e moderne unisce funzionalità estetica e valorizzazione delle materie prime locali nella produzione artigianale."
   ],
