   "id": "z2d3fa135",
   "sez": "salute",
   "titolo": "Il Ghana avvia il monitoraggio di 21 giorni per i viaggiatori dai Paesi colpita da Ebola",
   "orig": "GHS to monitor travellers from Ebola-affected countries for 21 days - Health Ministry",
   "lead": "Il Servizio Sanitario del Ghana ha disposto il monitoraggio per 21 giorni dei passeggeri in arrivo dai Paesi colpiti da epidemie di Ebola. Il Ministero della Salute ha annunciato la misura nell'ambito di un piano straordinario di screening e prevenzione negli aeroporti internazionali, volto a impedire la diffusione del virus Bundibugyo nel Paese. Il protocollo prevede la sorveglianza dello stato di salute dei viaggiatori per coprire l'intero periodo di incubazione del virus e individuare tempestivamente eventuali casi sospetti.",
   "more": [
    "La febbre emorragica da virus Ebola è una malattia infettiva grave e potenziale causa di epidemie nei Paesi dell'Africa subsahariana. I controlli sanitari ai confini e il monitoraggio dei viaggiatori per ventuno giorni consentono alle autorità di prevenire la trasmissione del patogeno e proteggere la salute pubblica."
   ],
