   "id": "z6f2fb95e",
   "sez": "economia",
   "titolo": "La Thailandia approva un forte aumento delle tasse sui veicoli elettrici importati",
   "orig": "Autos hub Thailand approves steep tax hikes on imported EVs",
   "lead": "Il governo della Thailandia ha approvato un deciso aumento delle imposte di fabbricazione sui veicoli elettrici a batteria interamente importati dall'estero. A partire dal mese di gennaio, l'aliquota fiscale salirà dal 10% al 35%, come annunciato dal ministro delle Finanze Ekniti Nitithanprapas. La misura punta a incentivare la produzione locale e gli investimenti industriali all'interno del Paese, in un momento in cui i marchi cinesi stanno conquistando quote di mercato sempre più ampie nel settore automobilistico del Sud-est asiatico.",
   "more": [
    "La Thailandia è uno dei principali centri di produzione automobilistica del Sud-est asiatico. L'applicazione di dazi e imposte elevate sui veicoli completi importati spinge i fabbricanti stranieri ad assemblare le vetture direttamente negli stabilimenti locali, proteggendo l'occupazione e lo sviluppo tecnologico interno."
   ],
