   "id": "z8e2db9be",
   "sez": "mondo",
   "titolo": "Kenya: piano da 94 milioni di scellini per l'estensione della rete elettrica",
   "orig": "Government targets 1,198 households in Sh93.99m electricity expansion",
   "lead": "Il governo del Kenya ha avviato un programma di espansione della rete elettrica del valore di circa 94 milioni di scellini kenioti. L'intervento infrastrutturale è destinato a collegare alla rete elettrica nazionale quasi 1.200 nuclei familiari situati nella circoscrizione di Budalangi, all'interno della contea di Busia. Il piano si inserisce nella strategia nazionale volta ad ampliare la copertura energetica e a migliorare l'accesso alle risorse primarie per i cittadini delle aree rurali del Paese. Lo riferisce The Standard.",
   "more": [
    "L'elettrificazione delle zone rurali nei Paesi in via di sviluppo è un elemento chiave per promuovere lo sviluppo economico, migliorare le condizioni sanitarie e sostenere la scolarizzazione attraverso un accesso stabile all'energia per case e infrastrutture pubbliche."
   ],
