   "id": "z48d342c3",
   "sez": "economia",
   "titolo": "L'Unione Europea autorizza l'acquisizione di Mediamarkt-Saturn da parte della cinese JD.com",
   "orig": "EU genehmigt chinesische Übernahme von Mediamarkt-Saturn",
   "lead": "La Commissione Europea ha dato il via libera all'acquisizione del gruppo commerciale Mediamarkt-Saturn da parte del gigante tecnologico cinese JD.com. L'autorità antitrust comunitaria ha espresso parere favorevole dopo che la società acquirente ha formalmente garantito che l'operazione non distorcerà la libera concorrenza nel mercato interno e non beneficerà di sussidi statali sleali. L'intesa permette al gruppo asiatico dell'e-commerce di espandere significativamente la propria presenza fisica ed elettronica nella vendita di prodotti di consumo in Europa.",
   "more": [
    "Il controllo delle concentrazioni aziendali da parte della Commissione Europea serve a verificare che le acquisizioni societarie effettuate da imprese straniere non creino posizioni monopolistiche e rispettino le norme comunitarie sugli aiuti di Stato, garantendo una concorrenza equa all'interno del mercato unico."
   ],
