   "id": "zb1a9446b",
   "sez": "mondo",
   "titolo": "Spagna: la polizia sgombra l'accampamento per la casa a Puerta del Sol a Madrid",
   "orig": "Spanish police dismantle Madrid housing protest camp ahead of snap election",
   "lead": "La polizia spagnola ha completamente sgomberato la tendopoli allestita in piazza Puerta del Sol a Madrid, che per oltre un mese ha simboleggiato le proteste contro il caro affitti e la crisi abitativa nel Paese. Gli agenti di polizia e gli operatori della nettezza urbana sono intervenuti all'alba per rimuovere tende, strutture temporanee e detriti rimasti nella piazza principale della capitale. Le manifestazioni per il diritto all'alloggio avevano acceso un forte dibattito pubblico, contribuendo ad accelerare la decisione di convocare elezioni anticipate.",
   "more": [
    "Negli ultimi anni molte grandi città europee affrontano una grave crisi abitativa, causata dalla diminuzione degli alloggi a lungo termine e dall'aumento dei canoni di locazione. La difficoltà nel reperire case a prezzi accessibili ha generato ampie mobilitazioni popolari."
   ],
