   "id": "zf0eca68e",
   "sez": "mondo",
   "titolo": "Elezioni di metà mandato negli USA: accuse incrociate tra i candidati al Senato in Alaska",
   "orig": "Alaska Senate candidates trade accusations ahead of election",
   "lead": "Nelle battute finali prima delle elezioni di metà mandato negli Stati Uniti, i candidati al Senato in Alaska si scambiano vive accuse reciproche sui temi dell'economia e delle risorse energetiche. La sfida vede opposti il senatore repubblicano uscente Dan Sullivan e la sfidante democratica Mary Peltola. Competizioni elettorali particolarmente serrate si stanno svolgendo anche in altri Stati chiave come Iowa, Maine e New Hampshire, dove i candidati dei due schieramenti stanno rivolgendo gli ultimi appelli agli elettori per conquistare seggi decisivi.",
   "more": [
    "La composizione del Senato degli Stati Uniti è determinata da due senatori per ciascuno dei cinquanta Stati. L'assegnazione dei seggi in Stati tradizionalmente contesi o a bassa densità abitativa come l'Alaska risulta spesso determinante per stabilire il controllo dell'assemblea."
   ],
