   "sez": "mondo",
   "titolo": "Nigeria: il governatore Lawal celebra i vent'anni di incoronazione del Sultano di Sokoto",
   "orig": "20th coronation Anniversary: Gov Lawal hails Sultan as beacon of unity and stability",
   "lead": "Il governatore dello Stato di Zamfara, Dauda Lawal, ha reso omaggio al Sultano di Sokoto definendolo un punto di riferimento per l'unità e la stabilità del Paese. Il discorso è stato pronunciato presso il Centro Internazionale Congressi di Sokoto in occasione della settimana dedicata a Shaikh Usmanu Bin Fodiyo e dei festeggiamenti per il ventesimo anniversario dell'incoronazione del Sultano. La figura del Sultano resta un'autorità morale e religiosa di grande rilievo nella regione settentrionale della Nigeria. Lo riferisce Premium Times.",
   "more": [
    "In Nigeria i sovrani e le autorità tradizionali non detengono poteri governativi di tipo costituzionale, ma esercitano un ruolo di straordinaria influenza morale, sociale e di mediazione culturale, contribuendo a preservare la coesione sociale e la stabilità tra le varie componenti della popolazione."
   ],
